def match_distributor_collation(apps, schema_editor):
    """ตาราง Distributor เดิมอาจ collation ไม่ตรงกับค่า default ของ database (เช่น import มาจาก MariaDB)
    ถ้าไม่ปรับตารางใหม่ให้ตรงกัน MySQL จะสร้าง FK -> Distributor.id ไม่ได้ (error 3780)"""
    if schema_editor.connection.vendor != 'mysql':
        return
    with schema_editor.connection.cursor() as cursor:
        cursor.execute(
            "SELECT CHARACTER_SET_NAME, COLLATION_NAME FROM information_schema.COLUMNS "
            "WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'Distributor' AND COLUMN_NAME = 'id'"
        )
        row = cursor.fetchone()
    if row:
        for table in NEW_TABLES:
            schema_editor.execute("ALTER TABLE `%s` CONVERT TO CHARACTER SET %s COLLATE %s" % ((table,) + row))


