def seed_rules(apps, schema_editor):
    Group = apps.get_model('stock', 'DistributorRuleGroup')
    Rule = apps.get_model('stock', 'DistributorRule')
    groups = {key: Group.objects.create(name=name, order=i) for i, (key, name) in enumerate(RULE_GROUPS, start=1)}
    rules = {}
    for i, (code, name, description, parent, children_mode, group) in enumerate(RULES, start=1):
        rules[code] = Rule.objects.create(
            code=code, name=name, description=description, parent=rules.get(parent),
            children_mode=children_mode, mandatory_group=groups.get(group), order=i * 10,
        )


def unseed_rules(apps, schema_editor):
    apps.get_model('stock', 'DistributorRule').objects.filter(parent__isnull=False).delete()
    apps.get_model('stock', 'DistributorRule').objects.all().delete()
    apps.get_model('stock', 'DistributorRuleGroup').objects.all().delete()


